function validate([nums, k, x]) {
  if (!Array.isArray(nums) || nums.length < 1 || nums.length > 100000) return 'nums needs 1 to 10^5 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > nums.length) return 'k is between 1 and the length of nums.';
  if (!Number.isInteger(x) || x < 1 || x > k) return 'x is between 1 and k.';
  return null;
}

