function findXSum(nums, k, x) {
  const count = new Map();
  const top = [];
  const rest = [];
  let sum = 0;
  const compare = (a, b) => a[0] - b[0] || a[1] - b[1];
  const position = (list, key) => {
    let low = 0;
    let high = list.length;
    while (low < high) {
      const mid = (low + high) >> 1;
      if (compare(list[mid], key) < 0) low = mid + 1;
      else high = mid;
    }
    return low;
  };
  const insert = (list, key) => list.splice(position(list, key), 0, key);
  const remove = (list, key) => list.splice(position(list, key), 1);
  const moveUp = () => {
    const key = rest.pop();
    insert(top, key);
    sum += key[0] * key[1];
  };
  const moveDown = () => {
    const key = top.shift();
    insert(rest, key);
    sum -= key[0] * key[1];
  };
  const change = (value, delta) => {
    const old = count.get(value) || 0;
    if (old > 0 && top.length > 0 && compare([old, value], top[0]) >= 0) {
      remove(top, [old, value]);
      sum -= old * value;
    } else if (old > 0) {
      remove(rest, [old, value]);
    }
    count.set(value, old + delta);
    if (old + delta > 0) insert(rest, [old + delta, value]);
    while (top.length < x && rest.length > 0) moveUp();
    while (rest.length > 0 && compare(rest[rest.length - 1], top[0]) > 0) {
      moveDown();
      moveUp();
    }
  };
  const answer = [];
  for (let i = 0; i < nums.length; i++) {
    if (i >= k) change(nums[i - k], -1);
    change(nums[i], 1);
    if (i >= k - 1) answer.push(sum);
  }
  return answer;
}

