function findXSum(nums, k, x) {
  const answer = [];
  for (let start = 0; start + k <= nums.length; start++) {
    const freq = {};
    for (let j = start; j < start + k; j++) freq[nums[j]] = (freq[nums[j]] || 0) + 1;
    const ranked = Object.keys(freq).map(Number).map(v => [freq[v], v]);
    ranked.sort((a, b) => b[0] - a[0] || b[1] - a[1]);
    let total = 0;
    for (const [times, v] of ranked.slice(0, x)) total += times * v;
    answer.push(total);
  }
  return answer;
}

