function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 10);
  const k = size === 'large' ? 200 + Math.floor(rand() * 1801) : 1 + Math.floor(rand() * n);
  const x = 1 + Math.floor(rand() * (rand() < 0.5 ? Math.min(k, 8) : k));
  const big = rand() < 0.3;
  const poolSize = size === 'large' ? 1 + Math.floor(rand() * 300) : 1 + Math.floor(rand() * 5);
  const pool = Array.from({ length: poolSize }, (_, i) => big ? 1 + Math.floor(rand() * 1e9) : i + 1);
  // Squaring the draw skews the frequencies so that the ranking matters.
  const nums = Array.from({ length: n }, () => pool[Math.floor(rand() ** 2 * poolSize)]);
  return [nums, k, x];
}
